package com.wavetransakt.qr.service; import com.wavetransakt.qr.dto.WalletQrResponse; import com.wavetransakt.user.entity.User; import com.wavetransakt.user.repository.UserRepository; import com.wavetransakt.wallet.entity.Wallet; import com.wavetransakt.wallet.repository.WalletRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID; @Service @RequiredArgsConstructor public class WalletQrService { private final WalletRepository walletRepository; private final UserRepository userRepository; /** * Get the authenticated user's permanent wallet QR. */ @Transactional(readOnly = true) public WalletQrResponse getWalletQr(UUID userId) { User user = userRepository .findById(userId) .orElseThrow(() -> new IllegalArgumentException( "User not found" ) ); Wallet wallet = walletRepository .findByUserId(userId) .orElseThrow(() -> new IllegalArgumentException( "Wallet not found" ) ); validateWallet(wallet); String accountName = buildAccountName(user); String walletNumber = wallet.getWalletNumber(); String payload = buildWalletPayload(walletNumber); return WalletQrResponse.builder() .qrType("WALLET") .walletNumber(walletNumber) .accountName(accountName) .currency(wallet.getCurrency()) .payload(payload) .paymentEndpoint( "/api/v1/qr/wallet/" + walletNumber ) .build(); } /** * Get wallet QR information using wallet number. * * This does not perform a payment. */ @Transactional(readOnly = true) public WalletQrResponse getWalletQrByWalletNumber( String walletNumber ) { if (walletNumber == null || walletNumber.isBlank()) { throw new IllegalArgumentException( "Wallet number is required" ); } Wallet wallet = walletRepository .findByWalletNumber(walletNumber) .orElseThrow(() -> new IllegalArgumentException( "Wallet not found" ) ); validateWallet(wallet); User user = wallet.getUser(); if (user == null) { throw new IllegalArgumentException( "Wallet owner not found" ); } String accountName = buildAccountName(user); String payload = buildWalletPayload( wallet.getWalletNumber() ); return WalletQrResponse.builder() .qrType("WALLET") .walletNumber( wallet.getWalletNumber() ) .accountName(accountName) .currency(wallet.getCurrency()) .payload(payload) .paymentEndpoint( "/api/v1/qr/wallet/" + wallet.getWalletNumber() ) .build(); } /** * Resolve a scanned wallet QR. * * The QR itself only contains the wallet number. * Account information is retrieved from the database. */ @Transactional(readOnly = true) public WalletQrResponse resolveWalletQr( String payload ) { if (payload == null || payload.isBlank()) { throw new IllegalArgumentException( "QR payload is required" ); } String walletNumber = extractWalletNumber(payload); return getWalletQrByWalletNumber( walletNumber ); } /** * Validate wallet status. */ private void validateWallet( Wallet wallet ) { if (wallet == null) { throw new IllegalArgumentException( "Wallet not found" ); } if (wallet.getStatus() == null) { throw new IllegalArgumentException( "Wallet status is unavailable" ); } if (!wallet.getStatus() .name() .equals("ACTIVE")) { throw new IllegalArgumentException( "Wallet is not active" ); } } /** * Build the account name shown to the payer. */ private String buildAccountName( User user ) { String firstName = user.getFirstName() == null ? "" : user.getFirstName().trim(); String lastName = user.getLastName() == null ? "" : user.getLastName().trim(); String accountName = (firstName + " " + lastName).trim(); if (accountName.isBlank()) { throw new IllegalArgumentException( "Account name is unavailable" ); } return accountName; } /** * Permanent wallet QR payload. * * Example: * * WTW:WALLET:6728895265 * * No amount is stored in the QR. */ private String buildWalletPayload( String walletNumber ) { if (walletNumber == null || walletNumber.isBlank()) { throw new IllegalArgumentException( "Wallet number is required" ); } return "WTW:WALLET:" + walletNumber; } /** * Extract wallet number from a Wave Transakt * wallet QR payload. */ private String extractWalletNumber( String payload ) { final String prefix = "WTW:WALLET:"; if (!payload.startsWith(prefix)) { throw new IllegalArgumentException( "Invalid Wave Transakt wallet QR" ); } String walletNumber = payload.substring(prefix.length()).trim(); if (walletNumber.isBlank()) { throw new IllegalArgumentException( "Wallet number is missing from QR" ); } return walletNumber; } }